import math

def act(history):
    states = history['states']
    actions = history['actions']
    n = len(actions)
    targets = states[1:]
    menu = [[0.6,0.0],[0.519615242271,0.3],[0.3,0.519615242271],[0.0,0.6],[-0.3,0.519615242271],[-0.519615242271,0.3],[-0.6,0.0],[-0.519615242271,-0.3],[-0.3,-0.519615242271],[0.0,-0.6],[0.3,-0.519615242271],[0.519615242271,-0.3],[0.0,0.0]]
    def fv(d,x,y,u,v,t,pu,pv):
        k = d[0]
        if k == 'x': return x
        if k == 'y': return y
        if k == 'u': return u
        if k == 'v': return v
        if k == '1': return 1.0
        if k == 'xx': return x*x
        if k == 'xy': return x*y
        if k == 'yy': return y*y
        if k == 'xxx': return x*x*x
        if k == 'yyy': return y*y*y
        if k == 'xr2': return x*(x*x+y*y)
        if k == 'yr2': return y*(x*x+y*y)
        if k == 'sinx': return math.sin(x)
        if k == 'siny': return math.sin(y)
        if k == 'cosx': return math.cos(x)
        if k == 'cosy': return math.cos(y)
        if k == 'tanhx': return math.tanh(x)
        if k == 'tanhy': return math.tanh(y)
        if k == 'r': return math.sqrt(x*x+y*y)
        if k == 'uu': return u*u
        if k == 'uv': return u*v
        if k == 'vv': return v*v
        if k == 'xu': return x*u
        if k == 'xv': return x*v
        if k == 'yu': return y*u
        if k == 'yv': return y*v
        if k == 'pu': return pu
        if k == 'pv': return pv
        if k == 't': return t
        if k == 'st': return math.sin(d[1]*t)
        if k == 'ct': return math.cos(d[1]*t)
        if k == 'ru': return u*math.cos(d[1]*t)-v*math.sin(d[1]*t)
        if k == 'rv': return u*math.sin(d[1]*t)+v*math.cos(d[1]*t)
        if k == 'state_ru': return u*math.cos(d[1]*x)-v*math.sin(d[1]*x)
        if k == 'state_rv': return u*math.sin(d[1]*x)+v*math.cos(d[1]*x)
        if k == 'tanhu': return math.tanh(u)
        if k == 'tanhv': return math.tanh(v)
        if k == 'sinu': return math.sin(u)
        if k == 'sinv': return math.sin(v)
        if k == 'sw':
            return fv((d[2],),x,y,u,v,t,pu,pv) if t >= d[1] else 0.0
        return 0.0
    columns = {}
    def col(d):
        if d not in columns:
            columns[d] = [fv(d,states[t][0],states[t][1],actions[t][0],actions[t][1],t,actions[t-1][0] if t else 0.0,actions[t-1][1] if t else 0.0) for t in range(n)]
        return columns[d]
    models = []
    seen = {}
    def fit(spec,kind,ids=None,save=True):
        if ids is None: ids = list(range(n))
        m = len(ids)
        p = len(spec)
        if p >= m: return None
        key = tuple(spec)
        if save and key in seen: return seen[key]
        cc = [[col(d)[i] for i in ids] for d in spec]
        q = []
        rr = [[0.0]*p for _ in range(p)]
        for j in range(p):
            z = cc[j][:]
            original = math.sqrt(sum(a*a for a in z))
            for repeat in range(2):
                for k in range(j):
                    a = sum(q[k][i]*z[i] for i in range(m))
                    rr[k][j] += a
                    z = [z[i]-a*q[k][i] for i in range(m)]
            a = math.sqrt(sum(v*v for v in z))
            if a < 1e-11*max(1.0,original): return None
            rr[j][j] = a
            q.append([v/a for v in z])
        coefficients = []
        for k in range(2):
            b = [sum(q[j][i]*targets[ids[i]][k] for i in range(m)) for j in range(p)]
            c = [0.0]*p
            for j in range(p-1,-1,-1):
                c[j] = (b[j]-sum(rr[j][k]*c[k] for k in range(j+1,p)))/rr[j][j]
            coefficients.append(c)
        if max(abs(v) for c in coefficients for v in c) > 10000: return None
        residuals = [[targets[ids[i]][k]-sum(cc[j][i]*coefficients[k][j] for j in range(p)) for k in range(2)] for i in range(m)]
        lev = [sum(q[j][i]*q[j][i] for j in range(p)) for i in range(m)]
        error = max(abs(v) for row in residuals for v in row)
        cv = max(abs(residuals[i][k])/max(1e-10,1.0-lev[i]) for i in range(m) for k in range(2))
        model = {'kind':kind,'features':spec,'coefficients':coefficients,'max_residual':error,'loo_max_error':cv,'p':p}
        if save:
            models.append(model)
            seen[key] = model
        return model
    base = [(k,) for k in ['x','y','u','v']]
    extra = [(k,) for k in ['xx','xy','yy','xxx','yyy','sinx','siny','cosx','cosy','tanhx','tanhy','r','xr2','yr2','uu','uv','vv','pu','pv','t','xu','xv','yu','yv']]
    for constant in [False,True]:
