        fit(b,'stationary')
        for a in range(len(extra)):
            fit(b+[extra[a]],'sparse_nonlinear')
            for c in range(a+1,len(extra)):
                fit(b+[extra[a],extra[c]],'sparse_nonlinear')
        small = [(k,) for k in ['xx','xy','yy','xxx','yyy','sinx','siny','tanhx','tanhy','xr2','yr2']]
        for a in range(len(small)):
            for c in range(a+1,len(small)):
