    fit(base+[('1',),('xx',),('xy',),('yy',)],'quadratic')
    fit(base+[(k,) for k in ['xu','xv','yu','yv']],'bilinear')
    for delay in [1]:
        fit([('x',),('y',),('pu',),('pv',)],'delayed')
        fit([('x',),('y',),('pu',),('pv',),('1',)],'delayed')
    for pair in [('tanhu','tanhv'),('sinu','sinv')]:
        for constant in [False,True]:
            fit([('x',),('y',),(pair[0],),(pair[1],)]+([('1',)] if constant else []),'nonlinear_actuator')
    for switch in range(3,8):
        fit(base+[('sw',switch,k) for k in ['x','y','u','v']],'switched_all')
        fit(base+[('sw',switch,k) for k in ['u','v']],'switched_input')
        fit(base+[('sw',switch,k) for k in ['x','y']],'switched_state')
    def harmonic(w,mode,save=True):
        if mode == 0: spec = base+[('st',w),('ct',w)]
        elif mode == 1: spec = [('x',),('y',),('ru',w),('rv',w)]
        elif mode == 2: spec = [('x',),('y',),('ru',w),('rv',w),('1',)]
        else: spec = [('x',),('y',),('ru',w),('rv',w),('st',w),('ct',w)]
        return fit(spec,'harmonic_'+str(mode),save=save)
    for mode in range(4):
        grid = []
        for i in range(1,65):
            w = 0.05*i
            m = harmonic(w,mode)
            if m is not None: grid.append((m['loo_max_error'],w))
        grid.sort()
        for _,w in grid[:2]:
            lo = max(0.0001,w-0.05)
            hi = w+0.05
            for iteration in range(42):
                a = lo+(hi-lo)*0.3819660112501051
                b = lo+(hi-lo)*0.6180339887498949
                ma = harmonic(a,mode,False)
                mb = harmonic(b,mode,False)
                va = ma['loo_max_error'] if ma is not None else 1e9
                vb = mb['loo_max_error'] if mb is not None else 1e9
                if va < vb: hi = b
                else: lo = a
            harmonic((lo+hi)/2,mode)
    for w in [0.1,0.2,0.3,0.5,0.7,1.0,1.5,2.0]:
        fit([('x',),('y',),('state_ru',w),('state_rv',w)],'state_rotated_input')
        fit([('x',),('y',),('state_ru',w),('state_rv',w),('1',)],'state_rotated_input')
    by_cv = sorted(models,key=lambda m:m['loo_max_error'])
    by_fit = sorted(models,key=lambda m:m['max_residual'])
    exact = sorted([m for m in models if m['loo_max_error'] < 1e-7],key=lambda m:(m['p'],m['loo_max_error']))
    def predict(m,x,y,u,v,t,pu,pv):
        z = [fv(d,x,y,u,v,t,pu,pv) for d in m['features']]
        return [sum(a*b for a,b in zip(c,z)) for c in m['coefficients']]
    pool = exact if exact else by_cv
    selected = []
    for m in pool:
        x,y = states[-1]
        probes = [predict(m,x,y,u,v,n,actions[-1][0],actions[-1][1]) for u,v in menu]
        if all(max(abs(probes[i][k]-other[i][k]) for i in range(13) for k in range(2)) > 0.01 for other in [p[1] for p in selected]):
            selected.append((m,probes))
        if len(selected) >= 3: break
    plans = []
    for model,probes in selected:
        candidate_results = []
        for first in range(13):
            xx,yy = probes[first]
            rad = xx*xx+yy*yy
            if rad > 16:
                candidate_results.append({'action_id':first,'predicted_escape':True})
                continue
            beam = [(rad,xx,yy,[first],0.0,rad,rad,menu[first][0],menu[first][1])]
            for h in range(2,23):
                expanded = []
                for old in beam:
                    _,x,y,path,hold,cumulative,peak,pu,pv = old
                    for j in range(13):
                        u,v = menu[j]
                        nx,ny = predict(model,x,y,u,v,n+h-1,pu,pv)
                        r = nx*nx+ny*ny
                        if r > 16: continue
                        nhold = max(hold,r) if n+h >= 28 else hold
                        ncum = cumulative+r
                        score = r+0.0005*ncum+1000.0*nhold
                        expanded.append((score,nx,ny,path+[j],nhold,ncum,max(peak,r),u,v))
