            if not beam:
                candidate_results.append({'action_id':first,'predicted_escape':True})
                continue
            best = min(beam,key=lambda b:(b[4],b[0]))
            candidate_results.append({'action_id':first,'predicted_escape':False,'max_target_norm':math.sqrt(best[4]),'max_future_norm':math.sqrt(best[6]),'forecast_success':best[4] <= 0.0025,'sequence':best[3]})
        plans.append({'model':model,'next_states':probes,'candidates':candidate_results})
