import math

def act(history):
    states = history['states']
    actions = history['actions']
    n = len(actions)
    menu = [[0.6,0.0],[0.519615242271,0.3],[0.3,0.519615242271],[0.0,0.6],[-0.3,0.519615242271],[-0.519615242271,0.3],[-0.6,0.0],[-0.519615242271,-0.3],[-0.3,-0.519615242271],[0.0,-0.6],[0.3,-0.519615242271],[0.519615242271,-0.3],[0.0,0.0]]
    def fit(rows, targets):
        if not rows:
            return None
        m = len(rows[0])
        if len(rows) < m:
            return None
        q = []
        rr = [[0.0]*m for j in range(m)]
        for j in range(m):
            v = [row[j] for row in rows]
            for repeat in range(2):
                for i in range(j):
                    z = sum(q[i][k]*v[k] for k in range(len(v)))
                    rr[i][j] += z
                    v = [v[k]-z*q[i][k] for k in range(len(v))]
            z = math.sqrt(sum(a*a for a in v))
            if z < 1e-12:
                return None
            rr[j][j] = z
            q.append([a/z for a in v])
        out = []
        for d in range(2):
            rhs = [sum(q[j][k]*targets[k][d] for k in range(len(rows))) for j in range(m)]
            beta = [0.0]*m
            for j in range(m-1,-1,-1):
                beta[j] = (rhs[j]-sum(rr[j][k]*beta[k] for k in range(j+1,m)))/rr[j][j]
