    def predict(z,u,t,fitted):
        fv = features(z,u,t,fitted['model'])
        return sum(c*v for c,v in zip(fitted['co'],fv))
    results = []
    structures = [['z','zb','w'],['z','r2z','w'],['z','zb','r2z','w'],['z','zb','w','wb'],['z','zb','r2z','w','wb']]
    for arg in ['r','r2','x','a','t']:
        for k in range(-30,31):
            omega = k*(0.1 if arg=='t' else (0.4 if arg=='a' else 0.2))
            if k == 0 and arg != 'r': continue
            for keys in structures:
                sides = ['left','right'] if 'wb' in keys and k!=0 else ['left']
                for side in sides:
                    m = {'mode':'rot','arg':arg,'omega':omega,'side':side,'keys':keys}
                    fitted = fit(m)
                    if fitted is not None: results.append(fitted)
    for arg in ['x','r','t']:
        for k in range(1,41):
            omega = k*(0.08 if arg=='t' else 0.4)
            for constant in [False,True]:
                keys = ['z','zb','w','wb','sn','cs']+(['one'] if constant else [])
                fitted = fit({'mode':'trig','arg':arg,'omega':omega,'keys':keys})
                if fitted is not None: results.append(fitted)
    for k in range(1,21):
        for keys in structures:
            fitted = fit({'mode':'tanh','omega':k*0.5,'keys':keys})
            if fitted is not None: results.append(fitted)
    extras = [[],['one'],['z2','zb2','r2'],['r2z'],['zu','zv'],['zu','zv','zbu','zbv'],['u2','ub2','a2']]
    for extra in extras:
        fitted = fit({'mode':'plain','keys':['z','zb','w','wb']+extra})
        if fitted is not None: results.append(fitted)
    for center in [1.3,1.5,1.7,1.9]:
        for width in [0.08,0.2,0.4]:
            for extra in [['gz'],['gu','gub'],['gz','gu','gub']]:
                fitted = fit({'mode':'gate','center':center,'width':width,'keys':['z','zb','w','wb']+extra})
                if fitted is not None: results.append(fitted)
    ranked = sorted(results,key=lambda f:f['score'])
    seeds = []
    signatures = []
    for fitted in ranked:
        m = fitted['model']
        if m['mode'] not in ['rot','trig','tanh']: continue
        sig = [m['mode'],m.get('arg',''),m.get('side',''),m['keys']]
        if sig in signatures: continue
        seeds.append(fitted)
        signatures.append(sig)
        if len(seeds)>=7: break
    for seed in seeds:
        best = seed
        for level in [0.1,0.01,0.001]:
            center = best['model']['omega']
            for j in range(-10,11):
                m = dict(best['model'])
                m['omega'] = center+j*level
                if m['mode']=='tanh' and abs(m['omega'])<0.01: continue
                fitted = fit(m)
                if fitted is not None:
                    results.append(fitted)
                    if fitted['score'] < best['score']: best = fitted
    ranked = sorted(results,key=lambda f:f['score'])
    summaries = []
    seen = []
    representative = []
    for fitted in ranked:
        m = fitted['model']
        signature = [m['mode'],m.get('arg',''),m.get('side',''),m['keys']]
        if signature in seen: continue
        seen.append(signature)
        preds = [predict(ss[-1],u,n,fitted) for u in menu]
        summary = {'model':m,'cv':fitted['cv'],'max_error':fitted['max_error'],'score':fitted['score'],'coefficients':[[c.real,c.imag] for c in fitted['co']],'next_states':[[z.real,z.imag] for z in preds],'next_norms':[abs(z) for z in preds]}
        summaries.append(summary)
        representative.append(fitted)
        if len(summaries)>=16: break
    selected = []
    selected_predictions = []
    limit = max(ranked[0]['score']*3.0,0.035)
    if ranked[0]['score']<1e-5: limit = max(1e-6,ranked[0]['score']*30.0)
    for fitted in representative:
        if fitted['score']>limit: continue
        preds = [predict(ss[-1],u,n,fitted) for u in menu]
        if selected and min(math.sqrt(sum(abs(preds[j]-old[j])**2 for j in range(13))/13.0) for old in selected_predictions)<0.025: continue
        selected.append(fitted)
        selected_predictions.append(preds)
        if len(selected)>=4: break
    if not selected:
        selected = [ranked[0]]
    def plan(fitted):
        rows = []
        for root in range(13):
            z0 = predict(ss[-1],menu[root],n,fitted)
            if abs(z0)>4.0:
                rows.append({'root':root,'escaped':True,'best_max_target_norm':1000000.0,'max_radius':abs(z0),'path':[root]})
                continue
            beam = [(z0,0.0,max(abs(ss[-1]),abs(z0)),[root])]
            failed = False
            for step in range(n+2,33):
                cells = {}
                for z,mt,mr,path in beam:
                    for j in range(13):
                        zz = predict(z,menu[j],step-1,fitted)
                        r = abs(zz)
                        if r>4.0: continue
                        mtt = max(mt,r) if step>=28 else mt
                        mrr = max(mr,r)
                        score = r*r+12.0*mtt*mtt+0.00001*mrr*mrr
                        cell_size = 0.003 if r<0.2 else 0.02
                        key = (int(math.floor(zz.real/cell_size)),int(math.floor(zz.imag/cell_size)))
                        previous = cells.get(key)
                        if previous is None or score<previous[0]:
                            cells[key] = (score,zz,mtt,mrr,path+[j])
                if not cells:
                    failed = True
                    break
                best_nodes = sorted(cells.values(),key=lambda v:v[0])[:24]
                beam = [(v[1],v[2],v[3],v[4]) for v in best_nodes]
            if failed:
                rows.append({'root':root,'escaped':True,'best_max_target_norm':1000000.0,'max_radius':4.0,'path':[root]})
            else:
                best = min(beam,key=lambda v:(v[1],abs(v[0]),v[2]))
                rows.append({'root':root,'escaped':False,'best_max_target_norm':best[1],'max_radius':best[2],'path':best[3]})
        return {'model':fitted['model'],'cv':fitted['cv'],'rows':rows}
    plans = [plan(fitted) for fitted in selected]
    return {'state_norm':abs(ss[-1]),'fitted_models':len(results),'ranked_distinct_models':summaries,'continuation_search':plans,'search_width':24,'target_steps':[28,29,30,31,32]}

def act(history):
    states = history['states']
    actions = history['actions']
    n = len(actions)
    def solve(a, b):
        a = [list(a[i]) + [b[i]] for i in range(len(b))]
        m = len(b)
        for j in range(m):
            k = max(range(j, m), key=lambda i: abs(a[i][j]))
            a[j], a[k] = a[k], a[j]
            if abs(a[j][j]) < 1e-18:
                return [0.0] * m
            z = a[j][j]
            a[j] = [v / z for v in a[j]]
            for i in range(m):
                if i != j:
                    z = a[i][j]
                    a[i] = [a[i][k] - z * a[j][k] for k in range(m + 1)]
        return [a[i][m] for i in range(m)]
    def features(i, kind):
        x, y = states[i]
        u, v = actions[i]
        f = [x, y, u, v]
        if kind >= 1:
            f += [1.0]
        if kind == 2:
            f += [x*x, x*y, y*y]
        if kind == 3:
            f += [float(i)]
        return f
    def fit(ids, kind):
        f = [features(i, kind) for i in ids]
        p = len(f[0])
        gram = [[sum(r[j]*r[k] for r in f) + (1e-12 if j == k else 0.0) for k in range(p)] for j in range(p)]
        return [solve(gram, [sum(f[z][j] * states[i+1][d] for z, i in enumerate(ids)) for j in range(p)]) for d in range(2)]
    out = []
    for kind in range(4):
        co = fit(list(range(n)), kind)
        residuals = [[states[i+1][d] - sum(a*b for a,b in zip(co[d],features(i,kind))) for d in range(2)] for i in range(n)]
        loo = []
        for i in range(n):
            c = fit([j for j in range(n) if j != i], kind)
            loo.append([states[i+1][d] - sum(a*b for a,b in zip(c[d],features(i,kind))) for d in range(2)])
        out.append({'kind':kind,'coefficients':co,'residuals':residuals,'loo_rmse':(sum(z*z for r in loo for z in r)/(2*n))**0.5})
    return {'models':out,'first_six_linear':fit(list(range(6)),0),'last_six_linear':fit(list(range(n-6,n)),0),'current_state':states[-1]}

